import 'outline_shape.dart';

/// One exterior view of a building type (Figma "Group 8" 652:2: frames A1..A3,
/// B1..B3, C1..C4, 3840x2160). [image] is the view's still, the Figma frame's
/// own render (exported at 1920x1080), so the traced outlines register to it;
/// it matches the first frame of [clip]. [clip] is the transition from this view to the next one and
/// [reverseClip] the same clip reversed (next view back to this one).
///
/// [floors] are the floor highlights traced on the view, top floor first (6F
/// .. GF), so floor i matches the building screen's floor index i.
class BuildingView {
  const BuildingView(this.type, this.number, this.floors);

  final String type;

  /// 1-based view number, as in the Figma frame names and the clip names.
  final int number;
  final List<OutlineShape> floors;

  String get _name => '${type.toLowerCase()}_$number';
  String get image => 'assets/images/building/views/$_name.jpg';
  String get clip => 'assets/videos/building/$_name.mp4';
  String get reverseClip => 'assets/videos/building/${_name}_reverse.mp4';

  /// Size of the Figma frames the outlines are traced on.
  static const figmaWidth = 3840.0;
  static const figmaHeight = 2160.0;

  /// The views of building type [type] in rotation order (empty when unknown).
  static List<BuildingView> of(String type) => _views[type] ?? const [];
}

